package io.github.polestarcn.companion;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
/** Private local energy observations. No network, maps, identifiers or third-party chart SDK. */
public final class EnergyActivity extends Activity {
 private LinearLayout page,results;private String vehicle;private int range=1,metric=0,generation;private boolean ac=true,dead;private long endTime;private int ink,muted;private final Handler main=new Handler(Looper.getMainLooper());
 private String tr(String a,String b){return AppPreferences.tr(this,a,b);}private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(ink);t.setPadding(12,8,12,8);return t;}
 private Button button(String value,Runnable click){Button b=new Button(this);b.setTextColor(ink);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(PsaDesign.surface(AppPreferences.dark(this))));b.setText(value);b.setOnClickListener(v->{Haptics.tap(this);click.run();});return b;}
 protected void attachBaseContext(Context c){super.attachBaseContext(UiTypography.wrap(c));}
 public void onCreate(Bundle state){super.onCreate(state);vehicle=getIntent().getStringExtra("vehicle");if(vehicle==null||!vehicle.matches("[a-fA-F0-9]{8,64}")){finish();return;}if(state!=null){range=state.getInt("range",1);metric=state.getInt("metric",0);ac=state.getBoolean("ac",true);endTime=state.getLong("endTime",0);}ink=PsaDesign.ink(AppPreferences.dark(this));muted=PsaDesign.muted(AppPreferences.dark(this));ScrollView scroll=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setBackgroundColor(PsaDesign.canvas(AppPreferences.dark(this)));scroll.addView(page);setContentView(scroll);
  page.addView(button(tr("返回车况","Back to condition"),this::finish));page.addView(text(tr("行驶 / 驻车空调能耗","Driving / parked climate energy"),22));
  page.addView(text(tr("71kWh参考电池 · 1% = 0.71kWh。驻车掉电包含其他车载负载，并非独立空调电表；行驶值为TM距离×均耗估算。缺失/间隔过长不推算。","71kWh reference battery · 1% = 0.71kWh. Parked loss includes other vehicle loads, not an HVAC meter. Driving is estimated from TM distance × average consumption. Missing or long gaps are excluded."),12));
  page.addView(button(tr("切换：空调 / 行驶","Switch: climate / driving"),()->{ac=!ac;load();}));
  Spinner periods=new Spinner(this);periods.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{tr("12H刻度 · 最近7天","12h · last 7 days"),tr("日 · 最近31天","Day · last 31 days"),tr("月 · 最近12月","Month · last 12 months"),tr("年 · 最近2年","Year · last 2 years")}){public View getView(int position,View convert,ViewGroup parent){View v=super.getView(position,convert,parent);if(v instanceof TextView)((TextView)v).setTextColor(ink);return v;}});periods.setSelection(range);periods.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){range=pos;load();}});page.addView(periods);page.addView(button(tr("选择截止日期（默认今天）","Select end date (today by default)"),this::date));
  page.addView(button(tr("曲线：总能耗 / TM均耗 / TM均速","Chart: total energy / TM consumption / speed"),()->{metric=(metric+1)%3;load();}));page.addView(button(tr("电价、保存期限与清空记录","Price, retention and clear history"),this::settings));results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);page.addView(results);load();}
 private void load(){if(results==null||dead)return;int request=++generation;results.removeAllViews();results.addView(text(tr("读取本机记录…","Loading local history…"),14));EnergyLog.WORK.execute(()->{try{EnergyLog.Report report=EnergyLog.get(this).read(vehicle,range,endTime==0?System.currentTimeMillis():endTime);main.post(()->{if(dead||request!=generation)return;results.removeAllViews();double kwh=ac?report.ac*.71:report.drive;results.addView(text((ac?tr("驻车空调估算","Parked climate estimate"):tr("TM行驶估算","TM driving estimate"))+String.format(Locale.getDefault()," · %.2f kWh · %.2f%% · %.2f",kwh,kwh/.71,kwh*EnergyLog.price(this))+tr(" 元 · 估算电费"," CNY · estimated cost"),17));results.addView(text(tr("采样记录：","Samples: ")+report.count+tr(" · 保留"," · retention ")+EnergyLog.months(this)+tr("个月"," months"),12));results.addView(text(ac?tr("曲线：驻车空调期间电量%","Chart: battery % during stationary climate"):metric==0?tr("曲线：区间累计行驶能耗 kWh","Chart: cumulative driving kWh"):metric==1?tr("曲线：TM平均能耗 kWh/100km","Chart: TM kWh/100km"):tr("曲线：TM平均速度 km/h","Chart: TM average km/h"),14));final Chart chart=new Chart(report);chart.setVisibility(View.GONE);Button expand=button(tr("展开 / 收起曲线","Expand / collapse chart"),()->chart.setVisibility(chart.getVisibility()==View.GONE?View.VISIBLE:View.GONE));results.addView(expand);results.addView(chart,new LinearLayout.LayoutParams(-1,(int)(240*getResources().getDisplayMetrics().density)));if(report.count==0)results.addView(text(tr("暂无记录。开启后随成功刷新自动采样；不会补造历史。","No records yet. Samples follow successful refreshes; history is never fabricated."),14));});}catch(Exception e){main.post(()->{if(!dead&&request==generation){results.removeAllViews();results.addView(text(tr("记录暂不可用，请稍后重试","History unavailable. Try again."),14));}});}});}
 private void date(){Calendar selected=Calendar.getInstance();if(endTime>0)selected.setTimeInMillis(endTime);DatePickerDialog picker=new DatePickerDialog(this,(view,year,month,day)->{Calendar date=Calendar.getInstance();date.set(year,month,day,23,59,59);endTime=date.getTimeInMillis();load();},selected.get(Calendar.YEAR),selected.get(Calendar.MONTH),selected.get(Calendar.DAY_OF_MONTH));Calendar first=Calendar.getInstance();first.add(Calendar.MONTH,-EnergyLog.months(this));picker.getDatePicker().setMinDate(first.getTimeInMillis());picker.getDatePicker().setMaxDate(System.currentTimeMillis());picker.show();}
 private void settings(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setBackgroundColor(PsaDesign.canvas(AppPreferences.dark(this)));p.addView(text(tr("电价（元/kWh）","Price per kWh"),14));EditText price=new EditText(this);price.setTextColor(ink);price.setText(""+EnergyLog.price(this));price.setInputType(8194);p.addView(price);p.addView(text(tr("保存月数（1–24，12个月=1年）","Retention months (1–24; 12 = 1 year)"),14));EditText months=new EditText(this);months.setTextColor(ink);months.setInputType(2);months.setText(""+EnergyLog.months(this));p.addView(months);AlertDialog dialog=new HapticDialogBuilder(this).setTitle(tr("能耗记录设置","Energy history settings")).setView(p).setPositiveButton(tr("保存","Save"),null).setNegativeButton(tr("取消","Cancel"),null).setNeutralButton(tr("清空数据库","Clear database"),(d,w)->new HapticDialogBuilder(this).setMessage(tr("清空本机所有车辆的能耗记录？无法恢复。","Delete all local vehicle energy history? This cannot be undone.")).setPositiveButton(tr("清空","Delete"),(x,y)->EnergyLog.WORK.execute(()->{try{EnergyLog.get(this).clear();main.post(this::load);}catch(Exception e){main.post(()->{if(!dead)Toast.makeText(this,tr("清空未完成，请重试","Clear failed; try again"),Toast.LENGTH_LONG).show();});}})).setNegativeButton(tr("取消","Cancel"),null).show()).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{try{double x=Double.parseDouble(price.getText().toString());int m=Integer.parseInt(months.getText().toString());if(!Double.isFinite(x)||x<0||x>100||m<1||m>24)throw new IllegalArgumentException();AppPreferences.set(this,"energy_price",""+x);AppPreferences.set(this,"energy_months",""+m);EnergyLog.WORK.execute(()->{try{EnergyLog.get(this).prune();main.post(this::load);}catch(Exception e){main.post(()->{if(!dead)Toast.makeText(this,tr("清理未完成，请重试","Cleanup failed; try again"),Toast.LENGTH_LONG).show();});}});dialog.dismiss();}catch(Exception e){months.setError(tr("电价0–100，保存1–24个月","Price 0–100; retention 1–24 months"));}});}
 protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putInt("range",range);b.putInt("metric",metric);b.putBoolean("ac",ac);b.putLong("endTime",endTime);}protected void onDestroy(){dead=true;generation++;main.removeCallbacksAndMessages(null);super.onDestroy();}
 private final class Chart extends View {final EnergyLog.Report report;final Paint paint=new Paint(3);Chart(EnergyLog.Report r){super(EnergyActivity.this);report=r;setContentDescription(tr("能耗时间曲线，汇总见上方文字","Energy timeline; accessible summary above"));}protected void onDraw(Canvas c){super.onDraw(c);float d=getResources().getDisplayMetrics().density,left=45*d,top=16*d,w=getWidth()-left-18*d,h=getHeight()-top-48*d;paint.setColor(muted);paint.setStrokeWidth(d);c.drawLine(left,top,left,top+h,paint);c.drawLine(left,top+h,left+w,top+h,paint);java.util.List<Double> values=new ArrayList<>();double total=0,max=1;for(EnergyLog.Point p:report.points){total+=p.drive;Double v=ac?p.soc:metric==0?total:metric==1?p.cons:p.speed;values.add(v);if(v!=null)max=Math.max(max,v);}if(ac)max=100;paint.setTextSize(10*d);c.drawText(String.format(Locale.getDefault(),"%.0f",max),3*d,top+10*d,paint);c.drawText("0",20*d,top+h,paint);float px=0,py=0;boolean previous=false;for(int i=0;i<values.size();i++){Double value=values.get(i);if(value==null){previous=false;continue;}float x=left+(values.size()==1?w/2:w*(report.points.get(i).t-report.points.get(0).t)/(float)Math.max(1,report.points.get(report.points.size()-1).t-report.points.get(0).t)),y=top+h-(float)(value/max)*h;paint.setColor(PsaDesign.ORANGE);paint.setStrokeWidth(2*d);if(previous)c.drawLine(px,py,x,y,paint);c.drawCircle(x,y,2*d,paint);px=x;py=y;previous=true;}paint.setColor(muted);for(int i=0;i<report.points.size();i++)if(i==0||i==report.points.size()-1||i==report.points.size()/2){String label=android.text.format.DateFormat.format(range==0?"MM-dd HH:mm":range==1?"MM-dd":range==2?"yyyy-MM":"yyyy",report.points.get(i).t).toString();float x=left+(report.points.size()==1?w/2:w*(report.points.get(i).t-report.points.get(0).t)/(float)Math.max(1,report.points.get(report.points.size()-1).t-report.points.get(0).t));c.drawText(label,Math.max(left,Math.min(x-paint.measureText(label)/2,getWidth()-paint.measureText(label))),top+h+20*d,paint);}}}
}
